import {SPECIALIST_FOODS,SPECIALIST_MEDICINES} from './specialist-supplies.js?v=0.87.0';
import {FRESH_MEAT} from './fresh-meat.js?v=0.87.0';
import {WINTER_PRESERVE} from './quest-rewards-data.js?v=0.90.41';
export const SHOPKEEPERS={marasenMarket:{id:"SHOP-PHI",name:"Marasen seed exchange",greeting:"Supplies for the green road."},marasenApothecary:{id:"SHOP-PHI",name:"Waterside apothecary",greeting:"Keep the living well."},marasenMill:{id:"SHOP-PHI",name:"Marasen mill",greeting:"Food for another journey."},marasenArchive:{id:"SHOP-PHI",name:"Archive dispatch counter",greeting:"Supplies for messengers."},cossenneConservatory:{id:'SHOP-PHI',name:'Graftkeepers’ Conservatory',greeting:'Resin for tree-dwellers, minerals for burrowers. Match the food to the partner you hope to meet.'},cossenneApothecary:{id:'SHOP-PHI',name:'Orchard Apothecary',greeting:'Dress the wound, restore strength, clear the sickness. These medicines help living partners.'},cossenneFirewatch:{id:'SHOP-PHI',name:'Firewatch Cistern',greeting:'Pack for an urgent rescue or a long watch. A safe road needs both.'},cossenneShop:{id:'SHOP-PHI',name:'Cossenne orchard provisioner',greeting:'Food for the forest and medicine for the smoke. We still have living trees to tend.'},cybressaShop:{id:'SHOP-PHI',name:'Cybressa market provisioner',greeting:'Grain, medicine and food for the roads beyond the city.'},shop:{id:'SHOP-CIV',name:'Civeton provisioner',greeting:'Pack enough for the journey home as well as the journey out.'},dorelemShop:{id:'SHOP-DOR',name:'Dorelem trader',greeting:'Bread for trust, medicine for mistakes. How much do you need?'},philomereShop:{id:'SHOP-PHI',name:'Philomere apothecary',greeting:'Keep your partners well. These supplies are set aside for travellers.'}};
SHOPKEEPERS.botruneShop={id:'SHOP-PHI',name:'Botrune garrison provisioner',greeting:'The square is silent. The bread still needs baking.'};
export const SHOP_STOCK=[{key:'binoculars',id:'binoculars',name:'Binoculars',price:500,text:'For eight battles, every living party member earns full EXP as if they participated. Activate from Field items; no EXP splitting.'},{key:'poultices',id:'poultice',name:'Poultice',price:300,text:'Restore 50% of maximum HP, up to 50 HP.'},{key:'bread',id:'bread',name:'Trail Bread',price:200,text:'Offer to a living wild Abyssal to recruit it.'},{key:'smoke',id:'smoke',name:'Smoke Bomb',price:400,text:'Guaranteed escape from an enemy trainer battle.'},{key:'emergencyEvacs',id:'emergency-evac',name:'Emergency Evac',price:800,text:'Summon horses and return instantly to your last priest rest point. Use in the overworld.'},{key:'armedEscorts',id:'armed-escort',name:'Armed Escort',price:500,text:'Prevent all wild Abyssal encounters for 200 steps. Trainers can still challenge you.'}];
export const HEARTY_FOOD_MODIFIER=2;
export const HEARTY_FOOD={key:'heartyFood',id:'hearty-food',name:'Hearty Ration',price:400,text:'Twice the capture strength of Trail Bread. Higher-level Abyssals are harder to recruit.'};
function baseShopStock(room){if(room.startsWith('marasen')||room.startsWith('botrune'))return [...SHOP_STOCK,HEARTY_FOOD,FRESH_MEAT,...SPECIALIST_FOODS,...SPECIALIST_MEDICINES];if(room==='cossenneConservatory')return SPECIALIST_FOODS;if(room==='cossenneApothecary')return SPECIALIST_MEDICINES;if(room==='cossenneFirewatch')return [...SHOP_STOCK.filter(i=>i.key!=='bread'),...SPECIALIST_FOODS.slice(4),SPECIALIST_MEDICINES[0]];if(room==='cossenneShop')return [...SHOP_STOCK.filter(item=>item.key!=='bread'),HEARTY_FOOD,FRESH_MEAT,...SPECIALIST_FOODS,...SPECIALIST_MEDICINES];if(room==='cybressaShop')return [...SHOP_STOCK.filter(item=>item.key!=='bread'),HEARTY_FOOD,FRESH_MEAT,SPECIALIST_FOODS[0],SPECIALIST_FOODS[4],SPECIALIST_MEDICINES[0]];return room==='shop'?SHOP_STOCK:[...SHOP_STOCK.filter(item=>item.key!=='bread'),HEARTY_FOOD];}
export function purchaseQuote(state,item,amount){const quantity=Number(amount),max=Math.floor(state.money/item.price),valid=Number.isSafeInteger(quantity)&&quantity>=1&&quantity<=max;return {quantity,max,valid,total:valid?quantity*item.price:0};}
export function buySupplies(state,item,amount){const q=purchaseQuote(state,item,amount);if(!q.valid)return false;state.money-=q.total;state[item.key]=(state[item.key]||0)+q.quantity;return true;}

export function shopStock(room,state=null){let stock=[...baseShopStock(room)];if(GENERAL_STORES.has(room)&&state?.generalStoreSupplies){const keys=new Set(stock.map(i=>i.key));for(const key of state.generalStoreSupplies){const item=generalCatalogue.get(key);if(item&&!keys.has(key)){stock.push(item);keys.add(key);}}}if(state?.questUnlocks?.winterRecipe)stock=[...stock,WINTER_PRESERVE];if(room.startsWith('cossenne')&&state?.cossenneServices?.relief?.claimed){const keys=new Set([...SPECIALIST_FOODS,...SPECIALIST_MEDICINES].map(i=>i.key));stock=stock.map(i=>keys.has(i.key)?{...i,price:Math.floor(i.price*.9),text:i.text+' Firewatch relief discount: 10%.'}:i);}return stock;}

// Named specialist counters and the Grand Exchange never join the general supply chain.
export const GENERAL_STORES=new Set(['shop','dorelemShop','philomereShop','cybressaShop','cossenneShop','botruneShop','marasen','cayfen','ramelle']);
const generalCatalogue=new Map([...GENERAL_STORES].flatMap(room=>baseShopStock(room)).map(item=>[item.key,item]));
export function unlockGeneralStore(state,room){
 if(!GENERAL_STORES.has(room))return false;
 const keys=new Set(state.generalStoreSupplies||[]);
 for(const item of baseShopStock(room))keys.add(item.key);
 state.generalStoreSupplies=[...keys];return true;
}

export function migrateGeneralStores(state,visited=[]){
 if(Array.isArray(state.generalStoreSupplies))return;
 state.generalStoreSupplies=[];
 const legacyStores={town:'shop',dorelem:'dorelemShop',philomere:'philomereShop',cybressa:'cybressaShop',cossenne:'cossenneShop',marasen:'marasen',botrune:'botruneShop',cayfen:'cayfen',ramelle:'ramelle'};
 for(const town of visited)if(legacyStores[town])unlockGeneralStore(state,legacyStores[town]);
}
